 g=b['goal'];first['decisions'].append({'goalId':g['goalId'],'goalFingerprint':g['goalFingerprint'],'pageFingerprint':g['pageFingerprint'],'decision':'keep','understandingEvidence':dict(zip(['essentialUnderstandingDe','essentialUnderstandingEn','observablePerformanceDe','observablePerformanceEn','transferExpectationDe','transferExpectationEn'],d[:6])),'currentContextReason':d[6],'evidenceProfileRecommendation':'none','recommendationScope':'No current-context-driven change to preserved V2 P material; not a new P approval.'})
